templates.template:
.bg {
    background: #d0d0d0;
    display: flex;
    position: relative;
	margin-top: 3px;
}

@media (max-width: @xf-messageSingleColumnWidth)
{
    .reputation-ranks 
    {
        width: 25%;
        display: flex;
        flex-direction: column;
        justify-content: center;
        flex: 0 0 auto;
        padding-top: 0 !important;
    }
}

.rankGreen {
    background: -webkit-linear-gradient(135deg, #009999 25%, #008283 25%, #008283 50%, #009999 50%, #009999 75%, #008283 75%);
    background: -moz-linear-gradient(135deg, #009999 25%, #008283 25%, #008283 50%, #009999 50%, #009999 75%, #008283 75%);
    background: -o-linear-gradient(135deg, #009999 25%, #008283 25%, #008283 50%, #009999 50%, #009999 75%, #008283 75%);
    width: {{$xf.options.rank_fullstar1}}%;
    height: 15px;
    background-size: 50px 50px;
    -webkit-animation: animasi 3.0s linear infinite;
    -moz-animation: animasi 3.0s linear infinite;
    -o-animation: animasi 3.0s linear infinite;
}

.rankRed {
    background: -webkit-linear-gradient(135deg, #E74C3C 25%, #C0392B 25%, #C0392B 50%, #E74C3C 50%, #E74C3C 75%, #C0392B 75%);
    background: -moz-linear-gradient(135deg, #E74C3C 25%, #C0392B 25%, #C0392B 50%, #E74C3C 50%, #E74C3C 75%, #C0392B 75%);
    background: -o-linear-gradient(135deg, #E74C3C 25%, #C0392B 25%, #C0392B 50%, #E74C3C 50%, #E74C3C 75%, #C0392B 75%);
    height: 15px;
    background-size: 50px 50px;
    -webkit-animation: animasi 3.0s linear infinite;
    -moz-animation: animasi 3.0s linear infinite;
    -o-animation: animasi 3.0s linear infinite;
}

.rankYellow {
    background: -webkit-linear-gradient(135deg, #F1C40F 25%, #F39C12 25%, #F39C12 50%, #F1C40F 50%, #F1C40F 75%, #F39C12 75%);
    background: -moz-linear-gradient(135deg, #F1C40F 25%, #F39C12 25%, #F39C12 50%, #F1C40F 50%, #F1C40F 75%, #F39C12 75%);
    background: -o-linear-gradient(135deg, #F1C40F 25%, #F39C12 25%, #F39C12 50%, #F1C40F 50%, #F1C40F 75%, #F39C12 75%);
    width: {{$xf.options.rank_completed}}%;
    height: 15px;
    background-size: 50px 50px;
    -webkit-animation: animasi 3.0s linear infinite;
    -moz-animation: animasi 3.0s linear infinite;
    -o-animation: animasi 3.0s linear infinite;
}

@-webkit-keyframes animasi {
    0% {
        background-position: 0 0;
    }
    100% {
        background-position: 50px 50px
    }
}

@-moz-keyframes animasi {
    0% {
        background-position: 0 0;
    }
    100% {
        background-position: 50px 50px
    }
}

@-o-keyframes animasi {
    0% {
        background-position: 0 0;
    }
    100% {
        background-position: 50px 50px
    }
}

.right {
    float: right;
    color: #fff;
    margin-top: 2px;
}

.left {
    float: left;
    color: #fff;
    margin-top: 2px;
}

.xentr-progress-bar {
	position: relative;
    margin-top: 3px;
    font-size: 12px;
}

@media (max-width: @xf-messageSingleColumnWidth)
{
    .reputation-ranks 
    {
        width: 25%;
        display: flex;
        flex-direction: column;
        justify-content: center;
        flex: 0 0 auto;
    }
}

progress[value] {
	appearance: none;
	border: none;
	width: 100%;
	height: 15px;
	background-color: whiteSmoke;
	border-radius: 3px;
	box-shadow: 0 2px 3px rgba(0, 0, 0, .5) inset;
	color: royalblue;
	position: relative;
	margin: 3px 0;
	&::-webkit-progress-bar {
		background-color: whiteSmoke;
		border-radius: 3px;
		box-shadow: 0 2px 3px rgba(0, 0, 0, .5) inset;
	}
	&::-webkit-progress-value {
		position: relative;
		background-size: 35px 20px, 100% 100%, 100% 100%;
		border-radius: 3px;
		animation: animate-stripes 5s linear infinite;
		&:after {
			content: '';
			position: absolute;
			width: 5px;
			height: 5px;
			top: 7px;
			right: 7px;
			background-color: white;
			border-radius: 100%;
		}
	}
	&::-moz-progress-bar {
		background-image: -moz-linear-gradient( 135deg, transparent, transparent 33%, rgba(0, 0, 0, .1) 33%, rgba(0, 0, 0, .1) 66%, transparent 66%), -moz-linear-gradient( top, rgba(255, 255, 255, .25), rgba(0, 0, 0, .2)), -moz-linear-gradient( left, #09c, #f44);
		background-size: 35px 20px, 100% 100%, 100% 100%;
		border-radius: 3px;
	}
}
.progress-bar {
	background-color: whiteSmoke;
	border-radius: 3px;
	box-shadow: 0 2px 3px rgba(0, 0, 0, .5) inset;
	width: 100%;
	height: 15px;
	span {
		background-color: royalblue;
		border-radius: 3px;
		display: block;
		text-indent: -9999px;
	}
}
p[data-value] {
	position: relative;
	margin: 0;
	color: @xf-textColorMuted;
	&:after {
		content: attr(data-value) '%';
		position: absolute;
		right: 0;
		color: @xf-textColor;
	}
}
.rankRed {
	&::-webkit-progress-value {
		background-image: -webkit-linear-gradient( 135deg, transparent, transparent 33%, rgba(0, 0, 0, .1) 33%, rgba(0, 0, 0, .1) 66%, transparent 66%), -webkit-linear-gradient( top, rgba(255, 255, 255, .25), rgba(0, 0, 0, .2)), -webkit-linear-gradient( left, #09c, #f44);
	}
	&::-moz-progress-bar {
		background-image: -moz-linear-gradient( 135deg, transparent, transparent 33%, rgba(0, 0, 0, .1) 33%, rgba(0, 0, 0, .1) 66%, transparent 66%), -moz-linear-gradient( top, rgba(255, 255, 255, .25), rgba(0, 0, 0, .2)), -moz-linear-gradient( left, #09c, #f44);
	}
}
.rankYellow {
	&::-webkit-progress-value {
		background-image: -webkit-linear-gradient( 135deg, transparent, transparent 33%, rgba(0, 0, 0, .1) 33%, rgba(0, 0, 0, .1) 66%, transparent 66%), -webkit-linear-gradient( top, rgba(255, 255, 255, .25), rgba(0, 0, 0, .2)), -webkit-linear-gradient( left, #09c, #ff0);
	}
	&::-moz-progress-bar {
		background-image: -moz-linear-gradient( 135deg, transparent, transparent 33%, rgba(0, 0, 0, .1) 33%, rgba(0, 0, 0, .1) 66%, transparent 66%), -moz-linear-gradient( top, rgba(255, 255, 255, .25), rgba(0, 0, 0, .2)), -moz-linear-gradient( left, #09c, #ff0);
	}
}
.rankGreen {
	&::-webkit-progress-value {
		background-image: -webkit-linear-gradient( 135deg, transparent, transparent 33%, rgba(0, 0, 0, .1) 33%, rgba(0, 0, 0, .1) 66%, transparent 66%), -webkit-linear-gradient( top, rgba(255, 255, 255, .25), rgba(0, 0, 0, .2)), -webkit-linear-gradient( left, #09c, #690);
	}
	&::-moz-progress-bar {
		background-image: -moz-linear-gradient( 135deg, transparent, transparent 33%, rgba(0, 0, 0, .1) 33%, rgba(0, 0, 0, .1) 66%, transparent 66%), -moz-linear-gradient( top, rgba(255, 255, 255, .25), rgba(0, 0, 0, .2)), -moz-linear-gradient( left, #09c, #690);
	}
}

@keyframes "animate-stripes" {
	100% {
		background-position: -100px 0;
	}
}

@media (max-width: @xf-messageSingleColumnWidth)
{
    .reputation-ranks 
    {
        width: 25%;
        display: flex;
        flex-direction: column;
        justify-content: center;
        flex: 0 0 auto;
    }
}
